import mapboxgl, {
  type GeoJSONSourceSpecification,
  type Map as MapboxMap,
  type MapMouseEvent,
} from "mapbox-gl";
import { Text, useColors } from "@/lib/ui";
import "mapbox-gl/dist/mapbox-gl.css";
import { useEffect, useRef } from "react";
import { StyleSheet, View } from "react-native";
import {
  camerasMatch,
  classifyMapHit,
  featuresToCollections,
  MAP_LAYER,
  MAP_LAYER_ORDER,
  MAP_SOURCE,
  MAPBOX_STYLE,
  type MapGeoJsonSourceSpec,
  type MapLayerSpec,
  MISSING_MAPBOX_TOKEN_MESSAGE,
  mapboxToken,
  mapOverlayLayers,
  NEWCASTLE,
  pointSource,
  shapeSource,
} from "./style";
import type { MapCamera, MapFeatureCollection, MapPosition, MapProps, MapSelection } from "./types";

type OverlayState = {
  features: MapFeatureCollection | undefined;
  cluster: boolean;
  selectedId: string | null;
};

export type WebMapHandlers = {
  onSelect?: (selection: MapSelection | null) => void;
  onCameraChange?: (camera: MapCamera) => void;
};

export type WebMapSession = {
  setOverlays: (
    features: MapFeatureCollection | undefined,
    cluster: boolean,
    selectedId: string | null,
  ) => void;
  setCamera: (center: MapPosition, zoom: number) => void;
  destroy: () => void;
};

function layersForSource(id: string): readonly string[] {
  if (id === MAP_SOURCE.points)
    return [MAP_LAYER.clusters, MAP_LAYER.clusterCount, MAP_LAYER.points];
  if (id === MAP_SOURCE.lines) return [MAP_LAYER.lines];
  return [MAP_LAYER.polygons, MAP_LAYER.polygonLine];
}

function syncSource(map: MapboxMap, id: string, spec: MapGeoJsonSourceSpec, recreate: boolean) {
  const existing = map.getSource(id);
  if (existing && !recreate && existing.type === "geojson") {
    existing.setData(spec.data as GeoJSONSourceSpecification["data"] & object);
    return;
  }
  if (existing) {
    for (const layerId of layersForSource(id)) {
      if (map.getLayer(layerId)) map.removeLayer(layerId);
    }
    map.removeSource(id);
  }
  map.addSource(id, spec as GeoJSONSourceSpecification);
}

function applyPaint(map: MapboxMap, layer: MapLayerSpec) {
  if (!layer.paint) return;
  for (const [key, value] of Object.entries(layer.paint)) {
    map.setPaintProperty(layer.id, key as never, value as never);
  }
}

function applyOverlays(
  map: MapboxMap,
  pending: OverlayState,
  previousCluster: boolean | undefined,
): boolean {
  const collections = featuresToCollections(pending.features);
  const recreatePoints = previousCluster !== undefined && previousCluster !== pending.cluster;
  syncSource(map, MAP_SOURCE.polygons, shapeSource(collections.polygons), false);
  syncSource(map, MAP_SOURCE.lines, shapeSource(collections.lines), false);
  syncSource(
    map,
    MAP_SOURCE.points,
    pointSource(collections.points, pending.cluster),
    recreatePoints,
  );
  for (const layer of mapOverlayLayers(pending.selectedId)) {
    if (!map.getLayer(layer.id)) map.addLayer(layer as never);
    else applyPaint(map, layer);
  }
  return pending.cluster;
}

function clusterCenter(
  geometry: { type?: string; coordinates?: unknown } | null | undefined,
): MapPosition | null {
  if (geometry?.type !== "Point" || !Array.isArray(geometry.coordinates)) return null;
  const lng = geometry.coordinates[0];
  const lat = geometry.coordinates[1];
  if (typeof lng !== "number" || typeof lat !== "number") return null;
  return [lng, lat];
}

function expandCluster(
  map: MapboxMap,
  clusterId: number,
  geometry: { type?: string; coordinates?: unknown },
) {
  const source = map.getSource(MAP_SOURCE.points);
  const center = clusterCenter(geometry);
  if (source?.type !== "geojson" || !center) return;
  source.getClusterExpansionZoom(clusterId, (error, zoom) => {
    if (error || zoom == null) return;
    map.easeTo({ center, zoom });
  });
}

/**
 * Web map: Mapbox GL JS on the light basemap, centred on Newcastle.
 * Device location is not requested. Attribution stays expanded so it stays visible.
 */
export function openWebMap(
  container: HTMLElement,
  camera: MapCamera,
  token: string,
  handlers: WebMapHandlers,
): WebMapSession {
  const map = new mapboxgl.Map({
    accessToken: token,
    container,
    style: MAPBOX_STYLE,
    center: camera.center,
    zoom: camera.zoom,
    attributionControl: false,
    logoPosition: "bottom-left",
  });
  map.addControl(new mapboxgl.AttributionControl({ compact: false }), "bottom-right");

  let loaded = false;
  let appliedCluster: boolean | undefined;
  let pending: OverlayState = { features: undefined, cluster: false, selectedId: null };

  const apply = () => {
    appliedCluster = applyOverlays(map, pending, appliedCluster);
  };

  map.on("load", () => {
    loaded = true;
    map.resize();
    apply();
  });

  map.on("click", (event: MapMouseEvent) => {
    const present = MAP_LAYER_ORDER.filter((id) => map.getLayer(id));
    const hits =
      present.length === 0 ? [] : map.queryRenderedFeatures(event.point, { layers: [...present] });
    const top = hits[0];
    if (!top) {
      handlers.onSelect?.(null);
      return;
    }
    const props =
      top.properties && typeof top.properties === "object"
        ? (top.properties as Record<string, unknown>)
        : null;
    const hit = classifyMapHit(props, top.id);
    if (hit.kind === "cluster") {
      expandCluster(map, hit.clusterId, top.geometry);
      return;
    }
    if (hit.kind === "feature") {
      handlers.onSelect?.({ id: hit.id });
      return;
    }
    handlers.onSelect?.(null);
  });

  map.on("moveend", () => {
    const center = map.getCenter();
    handlers.onCameraChange?.({
      center: [center.lng, center.lat],
      zoom: map.getZoom(),
    });
  });

  return {
    setOverlays(features, cluster, selectedId) {
      pending = { features, cluster, selectedId };
      if (loaded) apply();
    },
    setCamera(center, zoom) {
      const current = map.getCenter();
      const next = { center, zoom };
      if (camerasMatch({ lng: current.lng, lat: current.lat, zoom: map.getZoom() }, next)) return;
      map.jumpTo({ center, zoom });
    },
    destroy() {
      map.remove();
    },
  };
}

/** Web map. Metro loads this file instead of Map.native.tsx. */
export function MapView({
  center = NEWCASTLE,
  zoom = 13,
  style,
  features,
  cluster = false,
  selectedId = null,
  onSelect,
  onCameraChange,
}: MapProps) {
  const colors = useColors();
  const token = mapboxToken({
    EXPO_PUBLIC_MAPBOX_TOKEN: process.env.EXPO_PUBLIC_MAPBOX_TOKEN,
  });
  const container = useRef<HTMLDivElement>(null);
  const sessionRef = useRef<WebMapSession | null>(null);
  const handlers = useRef({ onSelect, onCameraChange });
  handlers.current = { onSelect, onCameraChange };
  const initialCamera = useRef<MapCamera>({ center, zoom });

  useEffect(() => {
    if (!container.current || !token) return;
    const session = openWebMap(container.current, initialCamera.current, token, {
      onSelect: (selection) => handlers.current.onSelect?.(selection),
      onCameraChange: (next) => handlers.current.onCameraChange?.(next),
    });
    sessionRef.current = session;
    return () => {
      session.destroy();
      sessionRef.current = null;
    };
  }, [token]);

  useEffect(() => {
    sessionRef.current?.setCamera(center, zoom);
  }, [center, zoom]);

  useEffect(() => {
    sessionRef.current?.setOverlays(features, cluster, selectedId);
  }, [features, cluster, selectedId]);

  if (!token) {
    return (
      <View
        style={[
          styles.map,
          styles.missing,
          { backgroundColor: colors.surface, borderColor: colors.border },
          style,
        ]}
      >
        <Text>{MISSING_MAPBOX_TOKEN_MESSAGE}</Text>
      </View>
    );
  }

  return (
    <View style={[styles.map, style]}>
      <div ref={container} style={{ position: "absolute", inset: 0 }} />
    </View>
  );
}

const styles = StyleSheet.create({
  map: { flex: 1, minHeight: 240 },
  missing: { borderWidth: 1, padding: 16, justifyContent: "center" },
});
=== style.ts
import type { StyleSpecification } from "maplibre-gl";
import type {
  MapCamera,
  MapFeatureCollection,
  MapFeatureProperties,
  MapGeometry,
  MapPosition,
} from "./types";

/** Newcastle city centre, [longitude, latitude] */
export const NEWCASTLE: [number, number] = [-1.614, 54.973];

export const OSM_ATTRIBUTION =
  '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors';

/**
 * OpenStreetMap raster tiles for the native map. The web map uses Mapbox.
 * Kept so Map.native.tsx can stay on MapLibre until that migration lands.
 */
export const osmStyle: StyleSpecification = {
  version: 8,
  sources: {
    osm: {
      type: "raster",
      tiles: ["https://tile.openstreetmap.org/{z}/{x}/{y}.png"],
      tileSize: 256,
      maxzoom: 19,
      attribution: OSM_ATTRIBUTION,
    },
  },
  layers: [{ id: "osm", type: "raster", source: "osm" }],
};

/** Restrained Mapbox basemap. The default Standard style is busier than this dashboard needs. */
export const MAPBOX_STYLE = "mapbox://styles/mapbox/light-v11";

export const MAPBOX_TOKEN_ENV = "EXPO_PUBLIC_MAPBOX_TOKEN";

export const MISSING_MAPBOX_TOKEN_MESSAGE =
  "Set EXPO_PUBLIC_MAPBOX_TOKEN to a Mapbox public token to show the Newcastle map.";

/** Ink, one accent, and white. Matches the app theme. No multi-hue scale. */
const INK = "#1a1a18";
const ACCENT = "#2f5bd3";
const ON_INK = "#ffffff";

const CLUSTER_RADIUS = 48;
const CLUSTER_MAX_ZOOM = 14;

export function mapboxToken(env?: { EXPO_PUBLIC_MAPBOX_TOKEN?: string }): string | undefined {
  const raw = env?.EXPO_PUBLIC_MAPBOX_TOKEN;
  if (typeof raw !== "string") return undefined;
  const token = raw.trim();
  return token.length > 0 ? token : undefined;
}

export const MAP_SOURCE = {
  points: "kip-points",
  lines: "kip-lines",
  polygons: "kip-polygons",
} as const;

export const MAP_LAYER = {
  polygons: "kip-polygons",
  polygonLine: "kip-polygon-line",
  lines: "kip-lines",
  clusters: "kip-clusters",
  clusterCount: "kip-cluster-count",
  points: "kip-points",
} as const;

/** Later entries draw above earlier ones. */
export const MAP_LAYER_ORDER = [
  MAP_LAYER.polygons,
  MAP_LAYER.polygonLine,
  MAP_LAYER.lines,
  MAP_LAYER.clusters,
  MAP_LAYER.clusterCount,
  MAP_LAYER.points,
] as const;

export type DrawnFeature = {
  type: "Feature";
  id: string;
  properties: MapFeatureProperties;
  geometry: MapGeometry;
};

export type DrawnCollection = {
  type: "FeatureCollection";
  features: DrawnFeature[];
};

export type MapGeoJsonSourceSpec = {
  type: "geojson";
  data: DrawnCollection;
  cluster?: boolean;
  clusterRadius?: number;
  clusterMaxZoom?: number;
};

export type MapLayerSpec = {
  id: string;
  type: "fill" | "line" | "circle" | "symbol";
  source: string;
  filter?: unknown[];
  layout?: Record<string, string | number | unknown[]>;
  paint?: Record<string, string | number | unknown[]>;
};

export type MapHit =
  | { kind: "cluster"; clusterId: number }
  | { kind: "feature"; id: string }
  | { kind: "empty" };

function emptyCollection(): DrawnCollection {
  return { type: "FeatureCollection", features: [] };
}

function isPosition(value: unknown): value is MapPosition {
  if (!Array.isArray(value) || value.length < 2) return false;
  const lng = value[0];
  const lat = value[1];
  return (
    typeof lng === "number" &&
    typeof lat === "number" &&
    Number.isFinite(lng) &&
    Number.isFinite(lat)
  );
}

function isLine(value: unknown): value is MapPosition[] {
  return Array.isArray(value) && value.length >= 2 && value.every(isPosition);
}

function isRing(value: unknown): value is MapPosition[] {
  return Array.isArray(value) && value.length >= 4 && value.every(isPosition);
}

function withId(
  id: string,
  properties: MapFeatureProperties | null | undefined,
): MapFeatureProperties {
  return { ...(properties ?? {}), id };
}

/** Split a feature collection into the three sources the web map draws. Invalid features are dropped. */
export function featuresToCollections(features: MapFeatureCollection | undefined): {
  points: DrawnCollection;
  lines: DrawnCollection;
  polygons: DrawnCollection;
} {
  const points = emptyCollection();
  const lines = emptyCollection();
  const polygons = emptyCollection();
  for (const feature of features?.features ?? []) {
    if (feature?.type !== "Feature" || feature.id.length === 0) continue;
    const drawn: DrawnFeature = {
      type: "Feature",
      id: feature.id,
      properties: withId(feature.id, feature.properties),
      geometry: feature.geometry,
    };
    if (feature.geometry.type === "Point" && isPosition(feature.geometry.coordinates)) {
      points.features.push(drawn);
    } else if (feature.geometry.type === "LineString" && isLine(feature.geometry.coordinates)) {
      lines.features.push(drawn);
    } else if (
      feature.geometry.type === "Polygon" &&
      feature.geometry.coordinates.length > 0 &&
      feature.geometry.coordinates.every(isRing)
    ) {
      polygons.features.push(drawn);
    }
  }
  return { points, lines, polygons };
}

export function shapeSource(data: DrawnCollection): MapGeoJsonSourceSpec {
  return { type: "geojson", data };
}

export function pointSource(data: DrawnCollection, cluster: boolean): MapGeoJsonSourceSpec {
  return {
    type: "geojson",
    data,
    cluster,
    clusterRadius: CLUSTER_RADIUS,
